static const HWt HW[7]={{h0_w,h0_b},{h1_w,h1_b},{h2_w,h2_b},{h3_w,h3_b},{h4_w,h4_b},{h5_w,h5_b},{h6_w,h6_b}};

/* noinline prevents the optimizer from reconstructing data-dependent max/select branches. */
__attribute__((noinline)) static uint64_t ct_mask64(uint64_t c){return UINT64_C(0)-(c&UINT64_C(1));}
__attribute__((noinline)) static uint32_t ct_mask32(uint32_t c){return 0u-(c&1u);}
__attribute__((noinline)) static int32_t ct_select_i32(uint32_t m,int32_t t,int32_t f){return (int32_t)(((uint32_t)t&m)|((uint32_t)f&~m));}
__attribute__((noinline)) static uint32_t ge_u64_u32(uint64_t a,uint32_t b){uint32_t hi=(uint32_t)(a>>32),lo=(uint32_t)a;return (uint32_t)((hi!=0u)|(lo>=b));}
__attribute__((noinline)) static uint32_t ge_u64_u64(uint64_t a,uint64_t b){uint32_t ah=(uint32_t)(a>>32),al=(uint32_t)a,bh=(uint32_t)(b>>32),bl=(uint32_t)b;return (uint32_t)(ah>bh)|((uint32_t)(ah==bh)&(uint32_t)(al>=bl));}

static int32_t rshift_round(int64_t a,unsigned n){uint64_t ua=(uint64_t)a,neg=ct_mask64(ua>>63);uint64_t mag=(ua^neg)+(neg&1u);uint64_t m=(mag+(UINT64_C(1)<<(n-1)))>>n;uint64_t sm=(m^neg)+(neg&1u);return (int32_t)sm;}
/* Fixed 64-iteration branchless restoring division: no hardware DIV or runtime helper required. */
static uint64_t udiv64_32_fixed(uint64_t num,uint32_t den){uint64_t q=0,rem=0;for(int i=63;i>=0;--i){uint64_t bit=(num>>(unsigned)i)&1u;rem=(rem<<1)|bit;uint64_t m=ct_mask64(ge_u64_u32(rem,den));rem-=((uint64_t)den)&m;q|=(UINT64_C(1)<<(unsigned)i)&m;}return q;}
/* Fixed 32-iteration branchless restoring integer square root. */
static uint32_t isqrt64_fixed(uint64_t x){uint64_t op=x,res=0,one=UINT64_C(1)<<62;for(int i=0;i<32;++i){uint64_t tmp=res+one,m=ct_mask64(ge_u64_u64(op,tmp));op-=tmp&m;res=(res>>1)+(one&m);one>>=2;}return (uint32_t)res;}
static void linear(const int32_t*w,const int32_t*b,const int32_t*x,int32_t*y,int out,int in){for(int o=0;o<out;++o){int64_t a=((int64_t)b[o])<<RTNN_FX_Q;for(int i=0;i<in;++i)a+=(int64_t)w[o*in+i]*x[i];y[o]=rshift_round(a,RTNN_FX_Q);}}
static void layernorm(const int32_t*x,int32_t*y,const int32_t*g,const int32_t*b){int64_t sm=0;for(int i=0;i<16;++i)sm+=x[i];int32_t m=rshift_round(sm,4);uint64_t vv=0;for(int i=0;i<16;++i){int64_t d=(int64_t)x[i]-m;vv+=(uint64_t)(d*d);}vv=(vv+8u)>>4;vv+=(uint64_t)(10.0e-6*RTNN_FX_S*RTNN_FX_S+0.5);uint32_t den=isqrt64_fixed(vv);uint64_t recip=udiv64_32_fixed(((uint64_t)RTNN_FX_S)<<20,den);for(int i=0;i<16;++i){int64_t d=(int64_t)x[i]-m;int32_t n=rshift_round(d*(int64_t)recip,20);y[i]=rshift_round((int64_t)n*g[i],RTNN_FX_Q)+b[i];}}
static uint32_t expq(int32_t x){const int32_t lo=-32*RTNN_FX_S,step=RTNN_FX_S/256;uint32_t mhi=ct_mask32((uint32_t)(x>0));int32_t xc=ct_select_i32(mhi,0,x);uint32_t mlo=ct_mask32((uint32_t)(xc<lo));xc=ct_select_i32(mlo,lo,xc);uint32_t off=(uint32_t)(xc-lo),i=off>>7,r=off&127u,top=i>>13;i-=top;r+=top<<7;uint64_t a=fx_exp_lut[i],bb=fx_exp_lut[i+1];return (uint32_t)((a*(step-r)+bb*r+(step/2))>>7);}
static int32_t geluq(int32_t x){const int32_t lo=-8*RTNN_FX_S,hi=8*RTNN_FX_S,step=RTNN_FX_S/256;uint32_t mhi=ct_mask32((uint32_t)(x>hi));int32_t xc=ct_select_i32(mhi,hi,x);uint32_t mlo=ct_mask32((uint32_t)(xc<lo));xc=ct_select_i32(mlo,lo,xc);uint32_t off=(uint32_t)(xc-lo),i=off>>7,r=off&127u,top=i>>12;i-=top;r+=top<<7;int64_t a=fx_gelu_lut[i],bb=fx_gelu_lut[i+1];return (int32_t)((a*(step-r)+bb*r+(step/2))>>7);}
static void init_state(RTNNFixedWorkspace*w,const uint8_t p[64]){int32_t in[8];for(int t=0;t<8;++t){for(int j=0;j<8;++j)in[j]=(int32_t)p[t*8+j]<<(RTNN_FX_Q-4);linear(emb_w,emb_b,in,w->h[t],16,8);for(int j=0;j<16;++j)w->h[t][j]+=pos[t*16+j];}}
static void run_block(RTNNFixedWorkspace*w,int bi){const BWt*q=&BW[bi];for(int t=0;t<8;++t)layernorm(w->h[t],w->x[t],q->n1w,q->n1b);for(int t=0;t<8;++t){int32_t y[48];linear(q->iw,q->ib,w->x[t],y,48,16);for(int j=0;j<16;++j){int hd=j/8,d=j%8;w->q[hd][t][d]=y[j];w->k[hd][t][d]=y[16+j];w->v[hd][t][d]=y[32+j];}}const int32_t scaleq=11585;for(int hd=0;hd<2;++hd)for(int tq=0;tq<8;++tq){int32_t sc[8],mx=INT32_MIN;for(int tk=0;tk<8;++tk){int64_t s=0;for(int d=0;d<8;++d)s+=(int64_t)w->q[hd][tq][d]*w->k[hd][tk][d];int32_t sq=rshift_round(s*scaleq,2*RTNN_FX_Q);sc[tk]=sq;uint32_t mm=ct_mask32((uint32_t)(sq>mx));mx=ct_select_i32(mm,sq,mx);}uint32_t ex[8],den=0;for(int tk=0;tk<8;++tk){ex[tk]=expq(sc[tk]-mx);den+=ex[tk];}uint64_t inv=udiv64_32_fixed(UINT64_C(1)<<46,den);for(int d=0;d<8;++d){int64_t s=0;for(int tk=0;tk<8;++tk){int32_t pq=(int32_t)(((uint64_t)ex[tk]*inv+(UINT64_C(1)<<30))>>31);s+=(int64_t)pq*w->v[hd][tk][d];}w->attcat[tq][hd*8+d]=rshift_round(s,15);}}for(int t=0;t<8;++t){linear(q->ow,q->ob,w->attcat[t],w->tmp[t],16,16);for(int j=0;j<16;++j)w->h[t][j]+=w->tmp[t][j];}for(int t=0;t<8;++t){layernorm(w->h[t],w->x[t],q->n2w,q->n2b);linear(q->aw,q->ab,w->x[t],w->ff[t],32,16);for(int j=0;j<32;++j)w->ff[t][j]=geluq(w->ff[t][j]);linear(q->bw,q->bb,w->ff[t],w->tmp[t],16,32);for(int j=0;j<16;++j)w->h[t][j]+=rshift_round((int64_t)w->tmp[t][j]*11469,15);}}
static void finish(const RTNNFixedWorkspace*w,uint8_t e,int32_t z[10]){int32_t m[16];for(int j=0;j<16;++j){int64_t s=0;for(int t=0;t<8;++t)s+=w->h[t][j];m[j]=rshift_round(s,3);}linear(HW[e].w,HW[e].b,m,z,10,16);}
static int32_t entropy10(const int32_t z[10]){int32_t mx=z[0];for(int i=1;i<10;++i){uint32_t mm=ct_mask32((uint32_t)(z[i]>mx));mx=ct_select_i32(mm,z[i],mx);}uint32_t ex[10],den=0;for(int i=0;i<10;++i){ex[i]=expq(z[i]-mx);den+=ex[i];}uint64_t inv=udiv64_32_fixed(UINT64_C(1)<<48,den);uint32_t dd=den+RTNN_FX_PS,num=den-RTNN_FX_PS;uint64_t yq=udiv64_32_fixed(((uint64_t)num)<<RTNN_FX_PQ,dd);uint64_t y2=(yq*yq+(RTNN_FX_PS/2))>>RTNN_FX_PQ,term=yq,l=0;for(int n=1;n<=19;n+=2){l+=udiv64_32_fixed(term+(uint64_t)(n/2),(uint32_t)n);term=(term*y2+(RTNN_FX_PS/2))>>RTNN_FX_PQ;}int32_t logq=rshift_round((int64_t)(2*l),RTNN_FX_PQ-RTNN_FX_Q);int64_t weighted=0;for(int i=0;i<10;++i){int32_t pq=(int32_t)(((uint64_t)ex[i]*inv+(UINT64_C(1)<<32))>>33);weighted+=(int64_t)pq*(mx-z[i]);}return logq+rshift_round(weighted,15);}
uint8_t rtnn_fixed_budget_ceiling_q16(uint16_t b){return (uint8_t)(((uint32_t)b*6u)/65535u);}
void rtnn_fixed_infer_exit(RTNNFixedWorkspace*w,const uint8_t p[64],uint8_t e,int32_t z[10]){if(e>6)e=0;init_state(w,p);for(uint8_t i=0;i<e;++i)run_block(w,i);finish(w,e,z);}
uint8_t rtnn_fixed_preferred_exit(RTNNFixedWorkspace*w,const uint8_t p[64]){init_state(w,p);int32_t z[10];finish(w,0,z);for(uint8_t e=0;e<RTNN_FX_POLICY_MAX_EXIT;++e){if(entropy10(z)<=RTNN_FX_POLICY_TAU_Q)return e;run_block(w,e);finish(w,e+1,z);}return RTNN_FX_POLICY_MAX_EXIT;}
void rtnn_fixed_infer_budget(RTNNFixedWorkspace*w,const uint8_t p[64],uint16_t b,uint8_t deadline,int32_t z[10],uint8_t*executed){uint8_t allowed=rtnn_fixed_budget_ceiling_q16(b);if(deadline>6)deadline=0;if(deadline<allowed)allowed=deadline;if(RTNN_FX_POLICY_MAX_EXIT<allowed)allowed=RTNN_FX_POLICY_MAX_EXIT;init_state(w,p);finish(w,0,z);uint8_t e=0;while(e<allowed){if(entropy10(z)<=RTNN_FX_POLICY_TAU_Q)break;run_block(w,e);++e;finish(w,e,z);}if(executed)*executed=e;}
void rtnn_fixed_certify_class(RTNNFixedWorkspace*w,const uint8_t p[64],uint8_t cls,int32_t z[10]){if(cls>6u)cls=0u;if(RTNN_FX_POLICY_MAX_EXIT<cls)cls=RTNN_FX_POLICY_MAX_EXIT;init_state(w,p);finish(w,0,z);for(uint8_t e=0;e<cls;++e){(void)entropy10(z);run_block(w,e);finish(w,e+1,z);}}
